<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import PageHeading from '@/components/PageHeading.vue'
import TablePagination from '@/components/TablePagination.vue'
import { backend } from '@/services/backend'
import { useToast } from '@/composables/useToast'
import type { AuditLogRecord, AppProfile } from '@/services/contracts'
const logs = ref<AuditLogRecord[]>([]); const page = ref(1); const pageSize = ref(10); const profile = ref<AppProfile | null>(null); const query = ref(''); const loading = ref(true); const { show } = useToast()
const canView = computed(() => backend.provider === 'demo' || profile.value?.role === 'admin')
const filtered = computed(() => logs.value.filter(l => `${l.trackingNumber} ${l.action} ${l.oldStatus || ''} ${l.newStatus || ''} ${l.changedBy}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const paginatedLogs = computed(() => pageSize.value === 0 ? filtered.value : filtered.value.slice((page.value - 1) * pageSize.value, page.value * pageSize.value))
watch(query, () => { page.value = 1 })
async function load() { loading.value = true; try { profile.value = await backend.getProfile(); if (canView.value) logs.value = await backend.getAuditLogs(); else logs.value = [] } catch (e) { show(e instanceof Error ? e.message : 'Gagal memuat audit logs.', 'error'); logs.value = [] } finally { loading.value = false } }
onMounted(load)
function exportCsv() { const headers = ['id','shipment_id','tracking_number','action','old_status','new_status','changed_by','changed_at']; const rows = filtered.value.map(l => [l.id,l.shipmentId,l.trackingNumber,l.action,l.oldStatus || '',l.newStatus || '',l.changedBy,l.changedAt]); const esc = (v: string | number) => `"${String(v).replaceAll('"','""')}"`; const csv = [headers,...rows].map(r => r.map(esc).join(',')).join('\r\n'); const url = URL.createObjectURL(new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'})); const a = document.createElement('a'); a.href = url; a.download = 'trackest-audit-logs.csv'; a.click(); URL.revokeObjectURL(url); show(`Diekspor ${rows.length} audit log.`, 'success') }
const pretty = (v: string | null) => v ? v.replaceAll('_',' ') : '—'
</script>
<template><PageHeading title="Log audit" description="Riwayat perubahan status yang dicatat oleh trigger database." :info="backend.provider === 'supabase' ? 'Data berasal dari public.audit_logs. Akses dibatasi untuk admin; perubahan status dicatat oleh trigger database.' : 'Log pada mode demo hanya sementara dan bukan catatan database.'"><button class="button button-secondary" :disabled="!canView || loading" @click="exportCsv">Ekspor CSV</button><button class="button button-secondary" :disabled="loading" @click="load">Muat ulang</button></PageHeading><div v-if="backend.provider === 'supabase' && !canView && !loading" class="notice notice-warning"><strong>Akses dibatasi.</strong> Halaman audit hanya tersedia untuk role admin. Pembatasan juga diterapkan di PostgreSQL RLS.</div><section v-else class="panel list-panel"><div class="list-toolbar"><div class="search-field"><span>⌕</span><input v-model="query" placeholder="Cari tracking, aktor, aksi, atau status…" aria-label="Cari audit log" /></div><span class="muted-cell">{{ loading ? 'Memuat…' : `${filtered.length} catatan` }}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Waktu</th><th>Aktor</th><th>Aksi</th><th>Shipment</th><th>Status lama</th><th>Status baru</th></tr></thead><tbody><tr v-for="log in paginatedLogs" :key="log.id"><td>{{ log.changedAt }}</td><td><span class="recipient-name">{{ log.changedBy }}</span></td><td><span class="audit-action" :class="log.action === 'UPDATE' ? 'audit-violet' : 'audit-blue'">{{ log.action }}</span></td><td><span class="tracking-id">{{ log.trackingNumber }}</span></td><td>{{ pretty(log.oldStatus) }}</td><td>{{ pretty(log.newStatus) }}</td></tr><tr v-if="!loading && !filtered.length"><td colspan="6" class="empty-cell">Tidak ada catatan audit untuk filter ini.</td></tr></tbody></table></div><TablePagination v-model:page="page" v-model:page-size="pageSize" :total="filtered.length" item-label="catatan" /></section></template>
